"""Configuration management for tui-journal."""
import os
from dataclasses import dataclass, field
from typing import Optional

try:
    import tomllib
except ImportError:
    import tomli as tomllib  # type: ignore


@dataclass
class ExportConfig:
    show_confirmation: bool = True
    export_path: Optional[str] = None


@dataclass
class ExternalEditorConfig:
    auto_save: bool = False
    temp_file_extension: str = "txt"
    editor_command: Optional[str] = None


@dataclass
class JsonBackendConfig:
    file_path: str = ""


@dataclass
class SqliteBackendConfig:
    file_path: str = ""


@dataclass
class AppConfig:
    backend_type: str = "Sqlite"
    scroll_per_page: int = 5
    sync_os_clipboard: bool = False
    history_limit: int = 10
    colored_tags: bool = True
    datum_visibility: str = "show"  # show, hide, empty_line
    app_state_dir: str = ""
    export: ExportConfig = field(default_factory=ExportConfig)
    external_editor: ExternalEditorConfig = field(default_factory=ExternalEditorConfig)
    json_backend: JsonBackendConfig = field(default_factory=JsonBackendConfig)
    sqlite_backend: SqliteBackendConfig = field(default_factory=SqliteBackendConfig)


def get_default_config_dir() -> str:
    home = os.path.expanduser("~")
    return os.path.join(home, ".config", "tui-journal")


def get_default_data_dir() -> str:
    home = os.path.expanduser("~")
    return os.path.join(home, "tui-journal")


def get_default_state_dir() -> str:
    home = os.path.expanduser("~")
    return os.path.join(home, ".local", "state", "tui-journal")


def get_default_log_dir() -> str:
    home = os.path.expanduser("~")
    return os.path.join(home, ".cache", "tui-journal")


def load_config(config_dir: str) -> AppConfig:
    """Load configuration from the config directory."""
    config_file = os.path.join(config_dir, "config.toml")

    config = AppConfig()
    data_dir = get_default_data_dir()
    config.json_backend.file_path = os.path.join(data_dir, "entries.json")
    config.sqlite_backend.file_path = os.path.join(data_dir, "entries.db")
    config.app_state_dir = get_default_state_dir()

    if not os.path.exists(config_file):
        return config

    try:
        with open(config_file, 'rb') as f:
            raw = tomllib.load(f)
    except Exception as e:
        raise ValueError(f"Failed to read configuration file. Error infos: {e}")

    # Parse backend_type
    if 'backend_type' in raw:
        bt = raw['backend_type']
        if bt.lower() == 'json':
            config.backend_type = 'Json'
        elif bt.lower() == 'sqlite':
            config.backend_type = 'Sqlite'
        else:
            config.backend_type = bt

    if 'scroll_per_page' in raw:
        config.scroll_per_page = int(raw['scroll_per_page'])
    if 'sync_os_clipboard' in raw:
        config.sync_os_clipboard = bool(raw['sync_os_clipboard'])
    if 'history_limit' in raw:
        config.history_limit = int(raw['history_limit'])
    if 'colored_tags' in raw:
        config.colored_tags = bool(raw['colored_tags'])
    if 'datum_visibility' in raw:
        dv = raw['datum_visibility']
        valid = ['show', 'hide', 'empty_line']
        if dv not in valid:
            raise ValueError(
                f"TOML parse error at line 1, column 20\n  |\n1 | datum_visibility = \"{dv}\"\n  |                    {'~' * len(dv)}\n"
                f"unknown variant `{dv}`, expected one of `show`, `hide`, `empty_line`\n"
            )
        config.datum_visibility = dv
    if 'app_state_dir' in raw:
        config.app_state_dir = raw['app_state_dir']

    # Export section
    if 'export' in raw:
        exp = raw['export']
        if 'show_confirmation' in exp:
            config.export.show_confirmation = bool(exp['show_confirmation'])
        if 'export_path' in exp:
            config.export.export_path = exp['export_path']

    # External editor section
    if 'external_editor' in raw:
        ee = raw['external_editor']
        if 'auto_save' in ee:
            config.external_editor.auto_save = bool(ee['auto_save'])
        if 'temp_file_extension' in ee:
            config.external_editor.temp_file_extension = ee['temp_file_extension']
        if 'editor_command' in ee:
            config.external_editor.editor_command = ee['editor_command']

    # JSON backend section
    if 'json_backend' in raw:
        jb = raw['json_backend']
        if 'file_path' in jb:
            config.json_backend.file_path = jb['file_path']

    # SQLite backend section
    if 'sqlite_backend' in raw:
        sb = raw['sqlite_backend']
        if 'file_path' in sb:
            config.sqlite_backend.file_path = sb['file_path']

    return config


def format_config(config: AppConfig) -> str:
    """Format config as TOML for print-config command."""
    lines = []
    bt = config.backend_type
    lines.append(f'backend_type = "{bt}"')
    lines.append(f'scroll_per_page = {config.scroll_per_page}')
    lines.append(f'sync_os_clipboard = {str(config.sync_os_clipboard).lower()}')
    lines.append(f'history_limit = {config.history_limit}')
    lines.append(f'colored_tags = {str(config.colored_tags).lower()}')
    lines.append(f'datum_visibility = "{config.datum_visibility}"')
    lines.append(f'app_state_dir = "{config.app_state_dir}"')
    lines.append('')
    lines.append('[export]')
    lines.append(f'show_confirmation = {str(config.export.show_confirmation).lower()}')
    lines.append('')
    lines.append('[external_editor]')
    lines.append(f'auto_save = {str(config.external_editor.auto_save).lower()}')
    lines.append(f'temp_file_extension = "{config.external_editor.temp_file_extension}"')
    lines.append('')
    lines.append('[json_backend]')
    lines.append(f'file_path = "{config.json_backend.file_path}"')
    lines.append('')
    lines.append('[sqlite_backend]')
    lines.append(f'file_path = "{config.sqlite_backend.file_path}"')
    lines.append('')
    return '\n'.join(lines)
