        self.lines[self.cursor_row] = line[:self.cursor_col] + ch + line[self.cursor_col:]
        self.cursor_col += 1
        self.modified = True

    def insert_newline(self):
        line = self.lines[self.cursor_row]
        self.lines[self.cursor_row] = line[:self.cursor_col]
        self.lines.insert(self.cursor_row + 1, line[self.cursor_col:])
        self.cursor_row += 1
        self.cursor_col = 0
        self.modified = True

    def backspace(self):
        if self.cursor_col > 0:
            line = self.lines[self.cursor_row]
            self.lines[self.cursor_row] = line[:self.cursor_col-1] + line[self.cursor_col:]
            self.cursor_col -= 1
            self.modified = True
        elif self.cursor_row > 0:
            prev = self.lines[self.cursor_row - 1]
            curr = self.lines.pop(self.cursor_row)
            self.cursor_row -= 1
            self.cursor_col = len(prev)
            self.lines[self.cursor_row] = prev + curr
            self.modified = True

    def delete_forward(self):
        line = self.lines[self.cursor_row]
        if self.cursor_col < len(line):
            self.lines[self.cursor_row] = line[:self.cursor_col] + line[self.cursor_col+1:]
            self.modified = True
        elif self.cursor_row < len(self.lines) - 1:
            next_line = self.lines.pop(self.cursor_row + 1)
            self.lines[self.cursor_row] = line + next_line
            self.modified = True

    def delete_word_backward(self):
        line = self.lines[self.cursor_row]
        pos = self.cursor_col
        while pos > 0 and line[pos-1].isspace():
            pos -= 1
        while pos > 0 and not line[pos-1].isspace():
            pos -= 1
        self.lines[self.cursor_row] = line[:pos] + line[self.cursor_col:]
        self.cursor_col = pos
        self.modified = True

    def delete_word_forward(self):
        line = self.lines[self.cursor_row]
        pos = self.cursor_col
        while pos < len(line) and line[pos].isspace():
            pos += 1
        while pos < len(line) and not line[pos].isspace():
            pos += 1
        self.lines[self.cursor_row] = line[:self.cursor_col] + line[pos:]
        self.modified = True

    def move_word_forward(self):
        line = self.lines[self.cursor_row]
        pos = self.cursor_col
        while pos < len(line) and not line[pos].isspace():
            pos += 1
        while pos < len(line) and line[pos].isspace():
            pos += 1
        self.cursor_col = pos
        self._clamp()

    def move_word_backward(self):
        line = self.lines[self.cursor_row]
        pos = self.cursor_col
        while pos > 0 and line[pos-1].isspace():
            pos -= 1
        while pos > 0 and not line[pos-1].isspace():
            pos -= 1
        self.cursor_col = pos
        self._clamp()

    def vim_word_forward(self):
        line = self.lines[self.cursor_row]
        pos = self.cursor_col
        if pos >= len(line) - 1:
            if self.cursor_row < len(self.lines) - 1:
                self.cursor_row += 1
                self.cursor_col = 0
                self._clamp()
            return
        while pos < len(line) and not line[pos].isspace():
            pos += 1
        while pos < len(line) and line[pos].isspace():
            pos += 1
        self.cursor_col = min(pos, max(0, len(line) - 1))

    def vim_word_backward(self):
        line = self.lines[self.cursor_row]
        pos = self.cursor_col
        if pos == 0:
            if self.cursor_row > 0:
                self.cursor_row -= 1
                line = self.lines[self.cursor_row]
                self.cursor_col = max(0, len(line) - 1)
            return
        pos -= 1
        while pos > 0 and line[pos].isspace():
            pos -= 1
        while pos > 0 and not line[pos-1].isspace():
            pos -= 1
        self.cursor_col = pos

    def enter_normal(self):
        self.mode = self.NORMAL
        line = self.lines[self.cursor_row]
        if line and self.cursor_col >= len(line):
            self.cursor_col = len(line) - 1
        elif not line:
            self.cursor_col = 0
        self.visual_start = None

    def enter_insert(self, after=False):
        self.mode = self.INSERT
        if after:
            line = self.lines[self.cursor_row]
            self.cursor_col = min(self.cursor_col + 1, len(line))

    def enter_insert_line_start(self):
        self.mode = self.INSERT
        self.cursor_col = 0

    def enter_insert_line_end(self):
        self.mode = self.INSERT
        self.cursor_col = len(self.lines[self.cursor_row])

    def open_below(self):
        self.lines.insert(self.cursor_row + 1, '')
        self.cursor_row += 1
        self.cursor_col = 0
        self.mode = self.INSERT
        self.modified = True

    def open_above(self):
        self.lines.insert(self.cursor_row, '')
        self.cursor_col = 0
        self.mode = self.INSERT
        self.modified = True

    def enter_visual(self):
        self.mode = self.VISUAL
        self.visual_start = (self.cursor_row, self.cursor_col)

    def get_visual_selection(self):
        if self.mode != self.VISUAL or self.visual_start is None:
            return None
        sr, sc = self.visual_start
        er, ec = self.cursor_row, self.cursor_col
        if (sr, sc) > (er, ec):
            sr, sc, er, ec = er, ec, sr, sc
        return (sr, sc, er, ec)

    def delete_selection(self):
        sel = self.get_visual_selection()
        if sel is None:
            return
        sr, sc, er, ec = sel
        if sr == er:
            line = self.lines[sr]
            self.lines[sr] = line[:sc] + line[ec+1:]
        else:
            start_line = self.lines[sr][:sc]
            end_line = self.lines[er][ec+1:]
            self.lines[sr] = start_line + end_line
            del self.lines[sr+1:er+1]
        self.cursor_row = sr
        self.cursor_col = sc
        self.mode = self.NORMAL
        self.visual_start = None
        self._clamp()
        self.modified = True

    def get_selection_text(self) -> str:
        sel = self.get_visual_selection()
        if sel is None:
            return ''
        sr, sc, er, ec = sel
        if sr == er:
            return self.lines[sr][sc:ec+1]
        parts = [self.lines[sr][sc:]]
        for r in range(sr+1, er):
            parts.append(self.lines[r])
        parts.append(self.lines[er][:ec+1])
        return '\n'.join(parts)

    def vim_delete_line(self):
        if len(self.lines) > 1:
            self.lines.pop(self.cursor_row)
            if self.cursor_row >= len(self.lines):
                self.cursor_row = len(self.lines) - 1
        else:
            self.lines[0] = ''
        self._clamp()
        self.modified = True

    def vim_move_right(self):
        line = self.lines[self.cursor_row]
        if self.cursor_col < max(0, len(line) - 1):
            self.cursor_col += 1

    def vim_move_left(self):
        if self.cursor_col > 0:
            self.cursor_col -= 1

    def vim_move_up(self):
        if self.cursor_row > 0:
            self.cursor_row -= 1
            self._clamp()

    def vim_move_down(self):
        if self.cursor_row < len(self.lines) - 1:
            self.cursor_row += 1
            self._clamp()

    def emacs_move_up(self):
        if self.cursor_row > 0:
            self.cursor_row -= 1
            self._clamp()

    def emacs_move_down(self):
        if self.cursor_row < len(self.lines) - 1:
            self.cursor_row += 1
            self._clamp()

    def emacs_move_forward(self):
        line = self.lines[self.cursor_row]
        if self.cursor_col < len(line):
            self.cursor_col += 1
        elif self.cursor_row < len(self.lines) - 1:
            self.cursor_row += 1
            self.cursor_col = 0

    def emacs_move_backward(self):
        if self.cursor_col > 0:
            self.cursor_col -= 1
        elif self.cursor_row > 0:
            self.cursor_row -= 1
            self.cursor_col = len(self.lines[self.cursor_row])

    def move_to_start(self):
        self.cursor_col = 0

    def move_to_end(self):
        self.cursor_col = len(self.lines[self.cursor_row])


