                lines.append(combined)
            else:
                lines.append(date_str)
                lines.append(f"Priority: {entry.priority}")
        else:
            lines.append(date_str)
    elif datum_visibility == 'hide':
        if entry.priority is not None:
            lines.append(f"Priority: {entry.priority}")
    elif datum_visibility == 'empty_line':
        if entry.priority is not None:
            lines.append(f"Priority: {entry.priority}")
        else:
            lines.append('')

    if entry.tags:
        lines.append(' | '.join(entry.tags))

    return lines


class SortState:
    def __init__(self):
        self.order = 'Descending'
        self.applied = ['Date', 'Priority']
        self.available = ['Title']

    def sort_entries(self, entries: List[Entry]) -> List[Entry]:
        def key_fn(e: Entry):
            keys = []
            for c in self.applied:
                if c == 'Date':
                    dt = e.date
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=timezone.utc)
                    keys.append(dt.timestamp())
                elif c == 'Title':
                    keys.append(e.title.lower())
                elif c == 'Priority':
                    keys.append(e.priority if e.priority is not None else 0)
            return keys
        rev = (self.order == 'Descending')
        return sorted(entries, key=key_fn, reverse=rev)


class FilterState:
    def __init__(self):
        self.title = ''
        self.content = ''
        self.priority = ''
        self.selected_tags: List[str] = []
        self.match_logic = 'all'  # 'all' or 'any'

    def apply(self, entries: List[Entry]) -> List[Entry]:
        result = []
        for e in entries:
            criteria = []
            if self.title:
                criteria.append(self.title.lower() in e.title.lower())
            if self.content:
                criteria.append(self.content.lower() in e.content.lower())
            if self.priority:
                try:
                    p = int(self.priority)
                    criteria.append(e.priority == p)
                except ValueError:
                    criteria.append(False)
            if self.selected_tags:
                tag_match = any(t in e.tags for t in self.selected_tags)
                criteria.append(tag_match)
            if not criteria:
                result.append(e)
            elif self.match_logic == 'all':
                if all(criteria):
                    result.append(e)
            else:
                if any(criteria):
                    result.append(e)
        return result

    def is_active(self) -> bool:
        return bool(self.title or self.content or self.priority or self.selected_tags)


