def parse_date_str(s: str) -> Optional[datetime]:
    s = s.strip()
    for sep in ['-', '/', ',']:
        if sep in s:
            parts = s.split(sep)
            if len(parts) == 3:
                try:
                    day, month, year = int(parts[0]), int(parts[1]), int(parts[2])
                    return datetime(year, month, day, tzinfo=timezone.utc)
                except (ValueError, TypeError):
                    pass
    return None


def entry_display_lines(entry: Entry, inner_w: int, datum_vis: str) -> List[str]:
    lines = []
    # Title
    t = entry.title
    while len(t) > inner_w:
        lines.append(t[:inner_w])
        t = t[inner_w:]
    lines.append(t)
    # Date/priority
    if datum_vis == 'show':
        ds = format_date(entry.date)
        if entry.priority is not None:
            combo = f"{ds} | Priority: {entry.priority}"
            if len(combo) <= inner_w:
                lines.append(combo)
            else:
                lines.append(ds)
                lines.append(f"Priority: {entry.priority}")
        else:
            lines.append(ds)
    elif datum_vis == 'hide':
        if entry.priority is not None:
            lines.append(f"Priority: {entry.priority}")
    elif datum_vis == 'empty_line':
        if entry.priority is not None:
            lines.append(f"Priority: {entry.priority}")
        else:
            lines.append('')
    # Tags
    if entry.tags:
        lines.append(' | '.join(entry.tags))
    return lines


class EditorState:
    NORMAL = 'NORMAL'
    INSERT = 'INSERT'
    VISUAL = 'VISUAL'

    def __init__(self, content=''):
        self.lines = content.split('\n') if content else ['']
        self.row = 0
        self.col = 0
        self.mode = self.NORMAL
        self.modified = False
        self.scroll = 0
        self.vis_start = None

    def content(self):
        return '\n'.join(self.lines)

    def load(self, content):
        self.lines = content.split('\n') if content else ['']
        self.row = 0
        self.col = 0
        self.mode = self.NORMAL
        self.modified = False
        self.scroll = 0
        self.vis_start = None

    def clamp(self):
        self.row = max(0, min(self.row, len(self.lines) - 1))
        line = self.lines[self.row]
        if self.mode == self.INSERT:
            self.col = max(0, min(self.col, len(line)))
        else:
            self.col = max(0, min(self.col, max(0, len(line) - 1)))

    def update_scroll(self, visible):
        if self.row < self.scroll:
            self.scroll = self.row
        elif self.row >= self.scroll + visible:
            self.scroll = self.row - visible + 1

    def insert_char(self, ch):
        line = self.lines[self.row]
        self.lines[self.row] = line[:self.col] + ch + line[self.col:]
        self.col += 1
        self.modified = True

    def newline(self):
        line = self.lines[self.row]
        self.lines[self.row] = line[:self.col]
        self.lines.insert(self.row + 1, line[self.col:])
        self.row += 1
        self.col = 0
        self.modified = True

    def backspace(self):
        if self.col > 0:
            line = self.lines[self.row]
            self.lines[self.row] = line[:self.col-1] + line[self.col:]
            self.col -= 1
            self.modified = True
        elif self.row > 0:
            prev = self.lines[self.row - 1]
            curr = self.lines.pop(self.row)
            self.row -= 1
            self.col = len(prev)
            self.lines[self.row] = prev + curr
            self.modified = True

    def del_forward(self):
        line = self.lines[self.row]
        if self.col < len(line):
            self.lines[self.row] = line[:self.col] + line[self.col+1:]
            self.modified = True
        elif self.row < len(self.lines) - 1:
            nxt = self.lines.pop(self.row + 1)
            self.lines[self.row] = line + nxt
            self.modified = True

    def del_word_back(self):
        line = self.lines[self.row]
        pos = self.col
        while pos > 0 and line[pos-1].isspace():
            pos -= 1
        while pos > 0 and not line[pos-1].isspace():
            pos -= 1
        self.lines[self.row] = line[:pos] + line[self.col:]
        self.col = pos
        self.modified = True

    def del_word_fwd(self):
        line = self.lines[self.row]
        pos = self.col
        while pos < len(line) and line[pos].isspace():
            pos += 1
        while pos < len(line) and not line[pos].isspace():
            pos += 1
        self.lines[self.row] = line[:self.col] + line[pos:]
        self.modified = True

    def word_fwd(self):
        line = self.lines[self.row]
        pos = self.col
        while pos < len(line) and not line[pos].isspace():
            pos += 1
        while pos < len(line) and line[pos].isspace():
            pos += 1
        self.col = pos
        self.clamp()

    def word_back(self):
        line = self.lines[self.row]
        pos = self.col
        while pos > 0 and line[pos-1].isspace():
            pos -= 1
        while pos > 0 and not line[pos-1].isspace():
            pos -= 1
        self.col = pos
        self.clamp()

    def vim_w(self):
        line = self.lines[self.row]
        pos = self.col
        if pos >= len(line) - 1:
            if self.row < len(self.lines) - 1:
                self.row += 1
                self.col = 0
                self.clamp()
            return
        while pos < len(line) and not line[pos].isspace():
            pos += 1
        while pos < len(line) and line[pos].isspace():
            pos += 1
        self.col = min(pos, max(0, len(line) - 1))

    def vim_b(self):
        line = self.lines[self.row]
        pos = self.col
        if pos == 0:
            if self.row > 0:
                self.row -= 1
                line = self.lines[self.row]
                self.col = max(0, len(line) - 1)
            return
        pos -= 1
        while pos > 0 and line[pos].isspace():
            pos -= 1
        while pos > 0 and not line[pos-1].isspace():
            pos -= 1
        self.col = pos

    def vim_dd(self):
        if len(self.lines) > 1:
            self.lines.pop(self.row)
            if self.row >= len(self.lines):
                self.row = len(self.lines) - 1
        else:
            self.lines[0] = ''
        self.clamp()
        self.modified = True

    def enter_normal(self):
        self.mode = self.NORMAL
        line = self.lines[self.row]
        if line and self.col >= len(line):
            self.col = len(line) - 1
        elif not line:
            self.col = 0
        self.vis_start = None

    def enter_insert(self, after=False):
        self.mode = self.INSERT
        if after:
            line = self.lines[self.row]
            self.col = min(self.col + 1, len(line))

    def enter_insert_sol(self):
        self.mode = self.INSERT
        self.col = 0

    def enter_insert_eol(self):
        self.mode = self.INSERT
        self.col = len(self.lines[self.row])

    def open_below(self):
        self.lines.insert(self.row + 1, '')
        self.row += 1
        self.col = 0
        self.mode = self.INSERT
        self.modified = True

    def open_above(self):
        self.lines.insert(self.row, '')
        self.col = 0
        self.mode = self.INSERT
        self.modified = True

    def enter_visual(self):
        self.mode = self.VISUAL
        self.vis_start = (self.row, self.col)

    def get_selection(self):
        if self.mode != self.VISUAL or self.vis_start is None:
            return None
        sr, sc = self.vis_start
        er, ec = self.row, self.col
        if (sr, sc) > (er, ec):
            sr, sc, er, ec = er, ec, sr, sc
        return (sr, sc, er, ec)

    def del_selection(self):
        sel = self.get_selection()
        if sel is None:
            return
        sr, sc, er, ec = sel
        if sr == er:
            line = self.lines[sr]
            self.lines[sr] = line[:sc] + line[ec+1:]
        else:
            sl = self.lines[sr][:sc]
            el = self.lines[er][ec+1:]
            self.lines[sr] = sl + el
            del self.lines[sr+1:er+1]
        self.row = sr
        self.col = sc
        self.mode = self.NORMAL
        self.vis_start = None
        self.clamp()
        self.modified = True

    def sel_text(self):
        sel = self.get_selection()
        if sel is None:
            return ''
        sr, sc, er, ec = sel
        if sr == er:
            return self.lines[sr][sc:ec+1]
        parts = [self.lines[sr][sc:]]
        for r in range(sr+1, er):
            parts.append(self.lines[r])
        parts.append(self.lines[er][:ec+1])
        return '\n'.join(parts)
