                    tag_match = not e.tags or any(t in e.tags for t in self.selected_tags if t != 'NO_TAGS')
                    if not e.tags:
                        tag_match = True
                    elif any(t in e.tags for t in self.selected_tags if t != 'NO_TAGS'):
                        tag_match = True
                    else:
                        tag_match = False
                else:
                    tag_match = any(t in e.tags for t in self.selected_tags)
                criteria.append(tag_match)
            if not criteria:
                result.append(e)
            elif self.match_logic == 'all':
                if all(criteria):
                    result.append(e)
            else:
                if any(criteria):
                    result.append(e)
        return result

    def is_active(self):
        return bool(self.title or self.content or self.priority or self.selected_tags)

    def logic_display(self):
        if self.match_logic == 'all':
            return 'Journals must meet all criteria'
