# ─── Sort/Filter State ───────────────────────────────────────────────────────
class SortState:
    def __init__(self):
        self.order = 'Descending'
        self.applied = ['Date', 'Priority']
        self.available = ['Title']

    def sort_entries(self, entries):
        def key_fn(e):
            keys = []
            for c in self.applied:
                if c == 'Date':
                    dt = e.date
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=timezone.utc)
                    keys.append(dt.timestamp())
                elif c == 'Title':
                    keys.append(e.title.lower())
                elif c == 'Priority':
                    keys.append(e.priority if e.priority is not None else 0)
            return keys
        return sorted(entries, key=key_fn, reverse=(self.order == 'Descending'))


class FilterState:
    def __init__(self):
        self.title = ''
        self.content = ''
        self.priority = ''
        self.selected_tags: List[str] = []
        self.match_logic = 'all'

    def apply(self, entries):
        result = []
        for e in entries:
            criteria = []
            if self.title:
                criteria.append(self.title.lower() in e.title.lower())
            if self.content:
                criteria.append(self.content.lower() in e.content.lower())
            if self.priority:
                try:
                    p = int(self.priority)
                    criteria.append(e.priority == p)
                except ValueError:
                    criteria.append(False)
            if self.selected_tags:
                if 'NO_TAGS' in self.selected_tags:
                    no_tag_match = not e.tags
                    other_tags = [t for t in self.selected_tags if t != 'NO_TAGS']
                    other_match = any(t in e.tags for t in other_tags)
                    tag_match = no_tag_match or other_match
                else:
                    tag_match = any(t in e.tags for t in self.selected_tags)
                criteria.append(tag_match)
            if not criteria:
                result.append(e)
            elif self.match_logic == 'all':
                if all(criteria):
                    result.append(e)
            else:
                if any(criteria):
                    result.append(e)
        return result

    def is_active(self):
        return bool(self.title or self.content or self.priority or self.selected_tags)

    def logic_display(self):
        if self.match_logic == 'all':
            return 'Journals must meet all criteria'
        return 'Journals must meet any criteria'


