# ─── Fuzzy Search ────────────────────────────────────────────────────────────
def fuzzy_score(pattern, text):
    if not pattern: return 0
    p = pattern.lower(); t = text.lower()
    if p in t: return 1000 - t.index(p)
    pi = 0; score = 0; last = -1
    for ti, tc in enumerate(t):
        if pi < len(p) and tc == p[pi]:
            gap = ti - last - 1 if last >= 0 else 0
            score += max(0, 10 - gap)
            last = ti; pi += 1
    return score if pi >= len(p) else -1

def fuzzy_search(query, entries):
    if not query: return []
    scored = []
    for e in entries:
        ts = fuzzy_score(query, e.title)
        cs = fuzzy_score(query, e.content) if e.content else -1
        best = max(ts, cs)
