def saddstr(win, y, x, s, attr=0):
    try:
        mh, mw = win.getmaxyx()
        if y < 0 or y >= mh or x < 0 or x >= mw: return
        avail = mw - x
        if avail <= 0: return
        win.addstr(y, x, s[:avail], attr)
    except curses.error:
        pass

def draw_box(win, y, x, h, w, title='', attr=0, heavy=False):
    if h < 2 or w < 2: return
    tl = BHTL if heavy else BTL
    tr = BHTR if heavy else BTR
    bl = BHBL if heavy else BBL
    br = BHBR if heavy else BBR
    inner = w - 2
    top_fill = BH * max(0, inner - len(title))
    saddstr(win, y, x, (tl + title + top_fill + tr)[:w], attr)
    saddstr(win, y+h-1, x, (bl + BH * inner + br)[:w], attr)
    for i in range(1, h-1):
        saddstr(win, y+i, x, BV, attr)
        saddstr(win, y+i, x+w-1, BV, attr)

def draw_input_field(win, y, x, w, label, field: InputField, focused, attr_normal=0, attr_active=0, attr_cursor=0):
    """Draw a 3-row input: border + label + value with cursor."""
    field_attr = attr_active if focused else attr_normal
    draw_box(win, y, x, 3, w, label, field_attr)
    inner_w = w - 4
    val = field.value
    cur = field.cursor
    # Scrolling view
    start = max(0, cur - inner_w + 1) if cur >= inner_w else 0
    visible = val[start:start + inner_w]
    rel_cur = cur - start
    saddstr(win, y+1, x+2, ' ' * inner_w, field_attr)
    saddstr(win, y+1, x+2, visible, field_attr)
    if focused:
        cur_ch = visible[rel_cur] if rel_cur < len(visible) else ' '
        saddstr(win, y+1, x+2+rel_cur, cur_ch, attr_cursor)

def fmt_date(dt):
    return f"{dt.day},{dt.month},{dt.year}"

def today_str():
    n = datetime.now(timezone.utc)
    return f"{n.day:02d}-{n.month:02d}-{n.year}"

def parse_date(s):
    s = s.strip()
    for sep in ['-', '/', ',']:
        if sep in s:
            parts = s.split(sep)
            if len(parts) == 3:
                try:
                    return datetime(int(parts[2]), int(parts[1]), int(parts[0]), tzinfo=timezone.utc)
                except (ValueError, TypeError):
                    pass
    return None

def entry_lines(entry, inner_w, datum_vis):
    lines = []
    t = entry.title
    while len(t) > inner_w:
        lines.append(t[:inner_w]); t = t[inner_w:]
    lines.append(t)
    if datum_vis == 'show':
        ds = fmt_date(entry.date)
        if entry.priority is not None:
            combo = f"{ds} | Priority: {entry.priority}"
            if len(combo) <= inner_w: lines.append(combo)
            else: lines.append(ds); lines.append(f"Priority: {entry.priority}")
        else:
            lines.append(ds)
    elif datum_vis == 'hide':
        if entry.priority is not None: lines.append(f"Priority: {entry.priority}")
    elif datum_vis == 'empty_line':
        if entry.priority is not None: lines.append(f"Priority: {entry.priority}")
        else: lines.append('')
    if entry.tags: lines.append(' | '.join(entry.tags))
    return lines

def get_all_tags(entries):
    tags = set()
    for e in entries:
        for t in e.tags: tags.add(t)
    return sorted(tags)

