                self.list_idx = len(self.display_entries) - 1; self._load_editor()
        elif key in (10, 13, curses.KEY_ENTER):
            if self._current_entry():
                self.state = self.ST_EDITOR
        elif key in (curses.KEY_DC, ord('d'), 4):  # Delete/d/Ctrl-d
            if self.dd_pending and key == ord('d'):
