        elif key in (ord('k'), curses.KEY_UP):
            if ed.row > 0: ed.row -= 1; ed.clamp()
        elif key in (ord('j'), curses.KEY_DOWN):
            if ed.row < len(ed.lines) - 1: ed.row += 1; ed.clamp()
        elif key == ord('w'):
            ed.vim_w()
        elif key == ord('b'):
            ed.vim_b()
        elif key == ord('g'):
            ed.row = 0; ed.clamp()
        elif key == ord('G'):
            ed.row = len(ed.lines) - 1; ed.clamp()
        elif key == ord('d'):
            if self.dd_pending:
                self.dd_pending = False; ed.vim_dd()
            else:
                self.dd_pending = True; return True
        elif key in (ord('s'), 19):  # s / Ctrl-s
            self._save_editor_to_entry()
