    def _handle_editor_insert(self, key):
        ed = self.editor
        if key in (27, 3):  # Esc/Ctrl-c
            ed.enter_normal()
        elif key in (10, 13):  # Enter
            ed.newline()
        elif key in (127, curses.KEY_BACKSPACE, 8):
            ed.backspace()
        elif key == curses.KEY_DC or key == 4:  # Delete/Ctrl-d
            ed.del_forward()
        elif key == curses.KEY_LEFT or key == 2:  # Ctrl-b
            if ed.col > 0: ed.col -= 1
            elif ed.row > 0: ed.row -= 1; ed.col = len(ed.lines[ed.row])
        elif key == curses.KEY_RIGHT or key == 6:  # Ctrl-f
            line = ed.lines[ed.row]
            if ed.col < len(line): ed.col += 1
            elif ed.row < len(ed.lines) - 1: ed.row += 1; ed.col = 0
        elif key == curses.KEY_UP or key == 16:  # Ctrl-p
            if ed.row > 0: ed.row -= 1; ed.clamp()
        elif key == curses.KEY_DOWN or key == 14:  # Ctrl-n
            if ed.row < len(ed.lines) - 1: ed.row += 1; ed.clamp()
        elif key == 1:  # Ctrl-a: line start
            ed.col = 0
        elif key == 5:  # Ctrl-e: line end
            ed.col = len(ed.lines[ed.row])
        elif key in (ord('s'), 19) and key == 19:  # Ctrl-s
            self._save_editor_to_entry()
        elif key == 17:  # Ctrl-q
            e = self._current_entry()
            if e and ed.modified: ed.load(e.content)
        elif key == 6:  # Ctrl-f (full screen)
            pass  # handled above via Ctrl-f already consumed
        elif key in (ord('y'), 25) and key == 25:  # Ctrl-y
            self._edit_external()
        elif 32 <= key <= 126 or key > 127:
            try:
                ed.insert_char(chr(key))
            except (ValueError, OverflowError):
                pass
