            if self.fuzzy_idx > 0:
                self.fuzzy_idx -= 1
                self._preview_fuzzy()
        else:
            self.fuzzy_query.handle_key(key)
            self._update_fuzzy()
        return True

    def _handle_tags_popup_key(self, key):
        if key in (27, 3):
            self.popup = self.popup_data.get('parent_popup')
        elif key in (10, 13, curses.KEY_ENTER):
            # Update the tags field
            tags_str = ','.join(sorted(self.tag_selected))
            parent = self.popup_data.get('parent_popup')
            if parent in (self.POP_CREATE, self.POP_EDIT):
                self.popup_fields[3].value = tags_str
                self.popup_fields[3].cursor = len(tags_str)
            self.popup = parent
        elif key == ord(' '):
            if self.tag_idx < len(self.tag_all):
                tag = self.tag_all[self.tag_idx]
                if tag in self.tag_selected: self.tag_selected.discard(tag)
                else: self.tag_selected.add(tag)
        elif key in (curses.KEY_DOWN, ord('j')):
            if self.tag_idx < len(self.tag_all) - 1: self.tag_idx += 1
        elif key in (curses.KEY_UP, ord('k')):
            if self.tag_idx > 0: self.tag_idx -= 1
        return True

    def _list_next(self):
        if self.list_idx < len(self.display_entries) - 1:
            self.list_idx += 1
            self._load_editor()

    def _list_prev(self):
        if self.list_idx > 0:
            self.list_idx -= 1
            self._load_editor()

    def _open_create_popup(self):
        today = today_str()
        self.popup_fields = [
            InputField('Title', ''),
            InputField('Date', today),
            InputField('Priority', ''),
