                foc = self.popup_focus
                if foc < len(self.popup_fields):
                    self.popup_fields[foc].handle_key(key, meta=True)
            elif self.popup == self.POP_FILTER:
                if self.filter_focus in (1, 2, 3) and self.filter_focus - 1 < len(self.popup_fields):
                    self.popup_fields[self.filter_focus - 1].handle_key(key, meta=True)
            elif self.popup == self.POP_FUZZY:
                self.fuzzy_query.handle_key(key, meta=True)
                self._update_fuzzy()
            elif self.popup in (self.POP_EXPORT_SINGLE, self.POP_EXPORT_MULTI):
                self.popup_fields[0].handle_key(key, meta=True)
            elif self.state == self.ST_EDITOR and self.editor.mode == EditorState.INSERT:
                if key in (ord('f'), ord('F')):
                    self.editor.word_fwd()
                elif key in (ord('b'), ord('B')):
                    self.editor.word_back()
                elif key in (ord('d'), ord('D')):
                    self.editor.del_word_fwd()
                elif key in (127, 8):
                    self.editor.del_word_back()
            return True

        if key == 27:  # ESC or start of meta sequence
            # Check for meta sequence (we'll just set pending)
            scr.timeout(50)
            next_key = scr.getch()
            scr.timeout(50)
            if next_key != -1:
                self.meta_pending = True
                # Re-process as meta
                self.meta_pending = False
                if self.popup == self.POP_CREATE or self.popup == self.POP_EDIT:
                    foc = self.popup_focus
                    if foc < len(self.popup_fields):
                        self.popup_fields[foc].handle_key(next_key, meta=True)
                elif self.popup == self.POP_FILTER:
                    if self.filter_focus in (1, 2, 3):
                        self.popup_fields[self.filter_focus - 1].handle_key(next_key, meta=True)
                elif self.popup == self.POP_FUZZY:
                    self.fuzzy_query.handle_key(next_key, meta=True)
                    self._update_fuzzy()
                elif self.state == self.ST_EDITOR and self.editor.mode == EditorState.INSERT:
                    if next_key in (ord('f'), ord('F')):
                        self.editor.word_fwd()
                    elif next_key in (ord('b'), ord('B')):
                        self.editor.word_back()
                    elif next_key in (ord('d'), ord('D')):
                        self.editor.del_word_fwd()
                    elif next_key in (127, 8):
                        self.editor.del_word_back()
                return True
            # Pure ESC
            key = 27

        # Handle popups first
        if self.popup == self.POP_INFO:
            if key in (10, 13, 27, ord('o'), ord('O'), curses.KEY_ENTER, ord(' ')):
                self.popup = None
            return True

        if self.popup == self.POP_HELP:
            return self._handle_help_key(key)

        if self.popup == self.POP_CREATE:
            return self._handle_create_key(key)

        if self.popup == self.POP_EDIT:
            return self._handle_edit_key(key)

        if self.popup == self.POP_DELETE:
            return self._handle_delete_key(key)

        if self.popup == self.POP_EXPORT_SINGLE:
            return self._handle_export_single_key(key)

        if self.popup == self.POP_EXPORT_MULTI:
            return self._handle_export_multi_key(key)

        if self.popup == self.POP_FILTER:
            return self._handle_filter_key(key)

        if self.popup == self.POP_SORT:
            return self._handle_sort_key(key)

        if self.popup == self.POP_FUZZY:
            return self._handle_fuzzy_key(key)

        if self.popup == self.POP_TAGS_CREATE:
            return self._handle_tags_popup_key(key)

        # Main state handling
        if self.state == self.ST_MULTI:
            return self._handle_multi_key(key)
        elif self.state == self.ST_EDITOR:
            return self._handle_editor_key(key)
        else:  # ST_LIST
            return self._handle_list_key(key)

    def _handle_list_key(self, key):
        if key == ord('q'):
            return False
        elif key == ord('?'):
            self.help_tab = 0; self.help_scroll = 0; self.popup = self.POP_HELP
        elif key in (ord('n'), ):
            self._open_create_popup()
        elif key == ord('e'):
            self._open_edit_popup()
        elif key in (curses.KEY_DOWN, ord('j')):
            self._list_next()
        elif key in (curses.KEY_UP, ord('k')):
            self._list_prev()
        elif key == curses.KEY_HOME:
            self.list_idx = 0; self._load_editor()
        elif key == curses.KEY_END:
            if self.display_entries:
                self.list_idx = len(self.display_entries) - 1; self._load_editor()
        elif key in (10, 13, curses.KEY_ENTER):
            if self._current_entry():
                self.state = self.ST_EDITOR
        elif key in (curses.KEY_DC, ord('d'), 4):  # Delete/d/Ctrl-d
            if self.dd_pending and key == ord('d'):
                self.dd_pending = False
                self._open_delete_popup()
            elif key == ord('d'):
                self.dd_pending = True
            else:
                self._open_delete_popup()
        elif key in (ord('s'), 19):  # s or Ctrl-s
            self._save_editor_to_entry()
        elif key == 17:  # Ctrl-q
            e = self._current_entry()
            if e and self.editor.modified:
                e.content  # discard
                self.editor.load(e.content)
        elif key == 18:  # Ctrl-r
            self.load()
        elif key == ord('>'):
            self._open_export_single()
        elif key in (ord('y'), 25):  # y or Ctrl-y
            self._edit_external()
        elif key == ord('v'):
            self.state = self.ST_MULTI
        elif key == ord('f'):
            self._open_filter()
        elif key == ord('x'):
            self.filter_state = FilterState()
            self._refresh_display()
        elif key == 20:  # Ctrl-t
            self._cycle_tag_filter()
        elif key in (ord('a'),) or key == ord('F') - 64 + 64:  # 'a' or Shift-F
            if key == ord('a') or key == ord('F'):
                self._open_fuzzy()
        elif key == 6:  # Ctrl-f
            self.full_screen = 'editor' if self.full_screen is None else None
        elif key in (9, 12):  # Tab or Ctrl-l
            self.state = self.ST_EDITOR
        elif key in (curses.KEY_BTAB, 8):  # BackTab or Ctrl-h
            pass
        elif key == ord('o'):
            self._open_sort()
        self.dd_pending = False if key != ord('d') else self.dd_pending
        return True

    def _handle_editor_key(self, key):
        mode = self.editor.mode
        if mode == EditorState.NORMAL:
            return self._handle_editor_normal(key)
        elif mode == EditorState.INSERT:
            return self._handle_editor_insert(key)
        elif mode == EditorState.VISUAL:
            return self._handle_editor_visual(key)
        return True

    def _handle_editor_normal(self, key):
        ed = self.editor
        if key == ord('q'):
            if not ed.modified:
                return False
            # Save first
            self._save_editor_to_entry()
            return False
        elif key == ord('?'):
            self.help_tab = 1; self.help_scroll = 0; self.popup = self.POP_HELP
        elif key in (27, 3, ord('[') - 64 + 1):  # Esc/Ctrl-c/Ctrl-[
            # Go back to list
            self.state = self.ST_LIST
        elif key in (10, 13, curses.KEY_ENTER):
            ed.enter_insert()
        elif key == ord('i'):
            ed.enter_insert()
        elif key == ord('I'):
            ed.enter_insert_sol()
        elif key == ord('a'):
            ed.enter_insert(after=True)
        elif key == ord('A'):
            ed.enter_insert_eol()
        elif key == ord('o'):
            ed.open_below()
        elif key == ord('O'):
            ed.open_above()
        elif key == ord('v'):
            ed.enter_visual()
        elif key in (ord('h'), curses.KEY_LEFT):
            if ed.col > 0: ed.col -= 1
        elif key in (ord('l'), curses.KEY_RIGHT):
            line = ed.lines[ed.row]
            if ed.col < max(0, len(line) - 1): ed.col += 1
        elif key in (ord('k'), curses.KEY_UP):
            if ed.row > 0: ed.row -= 1; ed.clamp()
        elif key in (ord('j'), curses.KEY_DOWN):
            if ed.row < len(ed.lines) - 1: ed.row += 1; ed.clamp()
        elif key == ord('w'):
            ed.vim_w()
        elif key == ord('b'):
            ed.vim_b()
        elif key == ord('g'):
            ed.row = 0; ed.clamp()
        elif key == ord('G'):
            ed.row = len(ed.lines) - 1; ed.clamp()
        elif key == ord('d'):
            if self.dd_pending:
                self.dd_pending = False; ed.vim_dd()
            else:
                self.dd_pending = True; return True
        elif key in (ord('s'), 19):  # s / Ctrl-s
            self._save_editor_to_entry()
        elif key == 17:  # Ctrl-q
            e = self._current_entry()
            if e and ed.modified:
                ed.load(e.content)
        elif key == ord('>'):
            self._open_export_single()
        elif key in (9, 12):  # Tab / Ctrl-l
            self.state = self.ST_LIST
        elif key in (curses.KEY_BTAB, 8):  # BackTab / Ctrl-h
            self.state = self.ST_LIST
        elif key == 6:  # Ctrl-f
            self.full_screen = 'editor' if self.full_screen is None else None
        elif key in (ord('y'), 25):  # y/Ctrl-y
            self._edit_external()
        self.dd_pending = False if key != ord('d') else self.dd_pending
        return True

    def _handle_editor_insert(self, key):
        ed = self.editor
        if key in (27, 3):  # Esc/Ctrl-c
            ed.enter_normal()
        elif key in (10, 13):  # Enter
            ed.newline()
        elif key in (127, curses.KEY_BACKSPACE, 8):
            ed.backspace()
        elif key == curses.KEY_DC or key == 4:  # Delete/Ctrl-d
            ed.del_forward()
        elif key == curses.KEY_LEFT or key == 2:  # Ctrl-b
            if ed.col > 0: ed.col -= 1
            elif ed.row > 0: ed.row -= 1; ed.col = len(ed.lines[ed.row])
        elif key == curses.KEY_RIGHT or key == 6:  # Ctrl-f
            line = ed.lines[ed.row]
            if ed.col < len(line): ed.col += 1
            elif ed.row < len(ed.lines) - 1: ed.row += 1; ed.col = 0
        elif key == curses.KEY_UP or key == 16:  # Ctrl-p
            if ed.row > 0: ed.row -= 1; ed.clamp()
        elif key == curses.KEY_DOWN or key == 14:  # Ctrl-n
            if ed.row < len(ed.lines) - 1: ed.row += 1; ed.clamp()
        elif key == 1:  # Ctrl-a: line start
            ed.col = 0
        elif key == 5:  # Ctrl-e: line end
            ed.col = len(ed.lines[ed.row])
        elif key in (ord('s'), 19) and key == 19:  # Ctrl-s
            self._save_editor_to_entry()
        elif key == 17:  # Ctrl-q
            e = self._current_entry()
            if e and ed.modified: ed.load(e.content)
        elif key == 6:  # Ctrl-f (full screen)
            pass  # handled above via Ctrl-f already consumed
        elif key in (ord('y'), 25) and key == 25:  # Ctrl-y
            self._edit_external()
        elif 32 <= key <= 126 or key > 127:
            try:
                ed.insert_char(chr(key))
            except (ValueError, OverflowError):
                pass
        return True

    def _handle_editor_visual(self, key):
        ed = self.editor
        if key in (27, 3):
            ed.enter_normal()
        elif key in (ord('h'), curses.KEY_LEFT):
            if ed.col > 0: ed.col -= 1
        elif key in (ord('l'), curses.KEY_RIGHT):
            line = ed.lines[ed.row]
            if ed.col < max(0, len(line) - 1): ed.col += 1
        elif key in (ord('k'), curses.KEY_UP):
            if ed.row > 0: ed.row -= 1; ed.clamp()
        elif key in (ord('j'), curses.KEY_DOWN):
            if ed.row < len(ed.lines) - 1: ed.row += 1; ed.clamp()
        elif key == ord('d') or key == ord('c'):
            ed.del_selection()
        elif key == ord('y'):
            # Yank (copy) - just enter normal mode
            ed.enter_normal()
        return True

    def _handle_multi_key(self, key):
        if key in (ord('q'), ord('v'), 27, 3):
            self.state = self.ST_LIST; self.multi_selected.clear()
        elif key == ord('?'):
            self.help_tab = 2; self.help_scroll = 0; self.popup = self.POP_HELP
        elif key in (curses.KEY_DOWN, ord('j')):
            self._list_next()
        elif key in (curses.KEY_UP, ord('k')):
            self._list_prev()
        elif key in (ord(' '), 10, 13, curses.KEY_ENTER):
            e = self._current_entry()
            if e:
                if e.id in self.multi_selected: self.multi_selected.discard(e.id)
                else: self.multi_selected.add(e.id)
        elif key == ord('a'):
            self.multi_selected = {e.id for e in self.display_entries}
        elif key == ord('x'):
            self.multi_selected.clear()
        elif key == ord('i'):
            all_ids = {e.id for e in self.display_entries}
            self.multi_selected = all_ids - self.multi_selected
        elif key in (ord('d'), curses.KEY_DC):
            self._delete_selected()
        elif key == ord('>'):
            self._open_export_multi()
        return True

    def _handle_help_key(self, key):
        tabs = ['Global', 'Editor', 'Multi-Select']
        if key in (27, 3, ord('q')):
            self.popup = None
        elif key in (9, curses.KEY_RIGHT):
            self.help_tab = (self.help_tab + 1) % len(tabs)
            self.help_scroll = 0
        elif key in (curses.KEY_BTAB, curses.KEY_LEFT):
            self.help_tab = (self.help_tab - 1) % len(tabs)
            self.help_scroll = 0
        elif key in (curses.KEY_DOWN, ord('j')):
            self.help_scroll += 1
        elif key in (curses.KEY_UP, ord('k')):
            if self.help_scroll > 0: self.help_scroll -= 1
        return True

    def _handle_create_key(self, key):
        foc = self.popup_focus
        if key in (27, 3):  # Esc/Ctrl-c
            self.popup = None
        elif key in (10, 13, curses.KEY_ENTER):
            if foc < 3:
                self.popup_focus = foc + 1
            else:
                self._confirm_create()
        elif key == 9:  # Tab
            self.popup_focus = (foc + 1) % 4
        elif key == curses.KEY_BTAB:
            self.popup_focus = (foc - 1) % 4
        elif key in (0, 20):  # Ctrl-Space or Ctrl-t: open tags
            self._open_tags_popup()
        else:
            if foc < len(self.popup_fields):
                self.popup_fields[foc].handle_key(key)
        return True

    def _handle_edit_key(self, key):
        foc = self.popup_focus
        if key in (27, 3):
            self.popup = None
        elif key in (10, 13, curses.KEY_ENTER):
            if foc < 3:
                self.popup_focus = foc + 1
            else:
                self._confirm_edit()
        elif key == 9:
            self.popup_focus = (foc + 1) % 4
        elif key == curses.KEY_BTAB:
            self.popup_focus = (foc - 1) % 4
        elif key in (0, 20):  # Ctrl-Space or Ctrl-t
            self._open_tags_popup()
        else:
            if foc < len(self.popup_fields):
                self.popup_fields[foc].handle_key(key)
        return True

    def _handle_delete_key(self, key):
        if key in (ord('y'), ord('Y')):
            self._confirm_delete()
        elif key in (ord('n'), ord('N'), 27, 3):
            self.popup = None
        return True

    def _handle_export_single_key(self, key):
        if key in (27, 3):
            self.popup = None
        elif key in (10, 13, curses.KEY_ENTER):
            self._confirm_export_single()
        else:
            self.popup_fields[0].handle_key(key)
        return True

    def _handle_export_multi_key(self, key):
        if key in (27, 3):
            self.popup = None
        elif key in (10, 13, curses.KEY_ENTER):
            self._confirm_export_multi()
        else:
            self.popup_fields[0].handle_key(key)
        return True

    def _handle_filter_key(self, key):
        foc = self.filter_focus
        all_tags = self.popup_data.get('all_tags', [])
        tag_list = all_tags + ['NO_TAGS']
        if key in (27, 3):
            self.popup = None
        elif key in (10, 13, curses.KEY_ENTER):
            # Apply filter
            self.filter_state.title = self.popup_fields[0].value
            self.filter_state.content = self.popup_fields[1].value
            self.filter_state.priority = self.popup_fields[2].value
            self._refresh_display()
            self.popup = None
        elif key == 9:  # Tab
            self.filter_focus = (foc + 1) % 5
        elif key == curses.KEY_BTAB:
            self.filter_focus = (foc - 1) % 5
        elif key == 18:  # Ctrl-r: toggle logic
            if self.filter_state.match_logic == 'all':
                self.filter_state.match_logic = 'any'
            else:
                self.filter_state.match_logic = 'all'
        elif key == ord(' ') and foc == 4:
            if self.filter_tags_idx < len(tag_list):
                tag = tag_list[self.filter_tags_idx]
                if tag in self.filter_state.selected_tags:
                    self.filter_state.selected_tags.remove(tag)
                else:
                    self.filter_state.selected_tags.append(tag)
        elif key in (curses.KEY_DOWN, ord('j')) and foc == 4:
            if self.filter_tags_idx < len(tag_list) - 1:
                self.filter_tags_idx += 1
        elif key in (curses.KEY_UP, ord('k')) and foc == 4:
            if self.filter_tags_idx > 0:
                self.filter_tags_idx -= 1
        else:
            if foc in (1, 2, 3):
                self.popup_fields[foc - 1].handle_key(key)
        return True

    def _handle_sort_key(self, key):
        foc = self.sort_focus
        if key in (27, 3):
            self.popup = None
        elif key in (10, 13, curses.KEY_ENTER):
            self._refresh_display()
            self.popup = None
        elif key == 9:  # Tab
            self.sort_focus = (foc + 1) % 3
        elif key == curses.KEY_BTAB:
            self.sort_focus = (foc - 1) % 3
        elif key == ord('o') and foc == 0:
            if self.sort_state.order == 'Descending':
                self.sort_state.order = 'Ascending'
            else:
                self.sort_state.order = 'Descending'
        elif key in (curses.KEY_DOWN, ord('j')):
            if foc == 1 and self.sort_avail_idx < len(self.sort_state.available) - 1:
                self.sort_avail_idx += 1
            elif foc == 2 and self.sort_applied_idx < len(self.sort_state.applied) - 1:
                self.sort_applied_idx += 1
        elif key in (curses.KEY_UP, ord('k')):
            if foc == 1 and self.sort_avail_idx > 0:
                self.sort_avail_idx -= 1
            elif foc == 2 and self.sort_applied_idx > 0:
                self.sort_applied_idx -= 1
        elif key == ord(' '):
            if foc == 1 and self.sort_state.available:
                crit = self.sort_state.available.pop(self.sort_avail_idx)
                self.sort_state.applied.append(crit)
                self.sort_avail_idx = max(0, self.sort_avail_idx - 1)
            elif foc == 2 and self.sort_state.applied:
                crit = self.sort_state.applied.pop(self.sort_applied_idx)
                self.sort_state.available.append(crit)
                self.sort_applied_idx = max(0, self.sort_applied_idx - 1)
        elif key == 4:  # Ctrl-d: load defaults
            self.sort_state.order = 'Descending'
            self.sort_state.applied = ['Date', 'Priority']
            self.sort_state.available = ['Title']
            self.sort_avail_idx = 0; self.sort_applied_idx = 0
        return True

    def _handle_fuzzy_key(self, key):
        if key in (27, 3):
            self.popup = None
        elif key in (10, 13, curses.KEY_ENTER):
            if self.fuzzy_results and 0 <= self.fuzzy_idx < len(self.fuzzy_results):
                target = self.fuzzy_results[self.fuzzy_idx]
                for i, e in enumerate(self.display_entries):
                    if e.id == target.id:
                        self.list_idx = i; self._load_editor(); break
            self.popup = None
        elif key in (curses.KEY_DOWN, ord('j')):
            if self.fuzzy_idx < len(self.fuzzy_results) - 1:
                self.fuzzy_idx += 1
                self._preview_fuzzy()
        elif key in (curses.KEY_UP, ord('k')):
            if self.fuzzy_idx > 0:
                self.fuzzy_idx -= 1
                self._preview_fuzzy()
        else:
            self.fuzzy_query.handle_key(key)
            self._update_fuzzy()
        return True

    def _handle_tags_popup_key(self, key):
        if key in (27, 3):
            self.popup = self.popup_data.get('parent_popup')
        elif key in (10, 13, curses.KEY_ENTER):
            # Update the tags field
            tags_str = ','.join(sorted(self.tag_selected))
            parent = self.popup_data.get('parent_popup')
            if parent in (self.POP_CREATE, self.POP_EDIT):
                self.popup_fields[3].value = tags_str
                self.popup_fields[3].cursor = len(tags_str)
            self.popup = parent
        elif key == ord(' '):
            if self.tag_idx < len(self.tag_all):
                tag = self.tag_all[self.tag_idx]
                if tag in self.tag_selected: self.tag_selected.discard(tag)
                else: self.tag_selected.add(tag)
        elif key in (curses.KEY_DOWN, ord('j')):
            if self.tag_idx < len(self.tag_all) - 1: self.tag_idx += 1
        elif key in (curses.KEY_UP, ord('k')):
            if self.tag_idx > 0: self.tag_idx -= 1
        return True

    def _list_next(self):
        if self.list_idx < len(self.display_entries) - 1:
            self.list_idx += 1
            self._load_editor()

    def _list_prev(self):
        if self.list_idx > 0:
            self.list_idx -= 1
            self._load_editor()

    def _open_create_popup(self):
        today = today_str()
        self.popup_fields = [
            InputField('Title', ''),
            InputField('Date', today),
            InputField('Priority', ''),
            InputField('Tags', ''),
        ]
        self.popup_focus = 0
        self.popup = self.POP_CREATE

    def _open_edit_popup(self):
        e = self._current_entry()
        if e is None: return
        dt = e.date
        today = f"{dt.day:02d}-{dt.month:02d}-{dt.year}"
        tags_str = ','.join(e.tags)
        self.popup_fields = [
            InputField('Title', e.title),
            InputField('Date', today),
            InputField('Priority', str(e.priority) if e.priority is not None else ''),
            InputField('Tags', tags_str),
        ]
        self.popup_focus = 0
        self.popup = self.POP_EDIT

    def _open_delete_popup(self):
        e = self._current_entry()
        if e is None: return
        self.popup_data = {'entry': e}
        self.popup = self.POP_DELETE

    def _open_export_single(self):
        e = self._current_entry()
        if e is None: return
        cwd = os.getcwd()
        ext = self.cfg.editor_temp_ext
        default_path = os.path.join(cwd, f"{e.title}.{ext}")
        self.popup_data = {'entry': e}
        self.popup_fields = [InputField('Path', default_path)]
        self.popup = self.POP_EXPORT_SINGLE

    def _open_export_multi(self):
        count = len(self.multi_selected)
        if count == 0: return
        cwd = os.getcwd()
        default_path = os.path.join(cwd, 'tjournal_export.json')
        self.popup_data = {'count': count}
        self.popup_fields = [InputField('Path', default_path)]
        self.popup = self.POP_EXPORT_MULTI

    def _open_filter(self):
        all_tags = get_all_tags(self.entries)
        self.popup_data = {'all_tags': all_tags}
        self.popup_fields = [
            InputField('Title', self.filter_state.title),
            InputField('Content', self.filter_state.content),
            InputField('Priority', self.filter_state.priority),
        ]
        self.filter_focus = 1
        self.filter_tags_idx = 0
        self.popup = self.POP_FILTER

    def _open_sort(self):
        self.sort_focus = 0
        self.sort_avail_idx = 0
        self.sort_applied_idx = 0
        self.popup = self.POP_SORT

    def _open_fuzzy(self):
        self.fuzzy_query = InputField('Search Query', '')
        self.fuzzy_results = []
        self.fuzzy_idx = 0
        self.popup = self.POP_FUZZY

    def _open_tags_popup(self):
        all_tags = get_all_tags(self.entries)
        self.tag_all = all_tags
        # Get current tags from field
        current_tags_str = self.popup_fields[3].value if len(self.popup_fields) > 3 else ''
        current_tags = {t.strip() for t in current_tags_str.split(',') if t.strip()}
        self.tag_selected = current_tags
        self.tag_idx = 0
        self.popup_data['parent_popup'] = self.popup
        self.popup = self.POP_TAGS_CREATE

    def _confirm_create(self):
        title = self.popup_fields[0].value.strip()
        if not title: return
        date_str = self.popup_fields[1].value.strip()
        dt = parse_date(date_str) or datetime.now(timezone.utc)
        priority_str = self.popup_fields[2].value.strip()
        priority = int(priority_str) if priority_str.isdigit() else None
        tags_str = self.popup_fields[3].value.strip()
        tags = [t.strip() for t in tags_str.split(',') if t.strip()]
        new_id = self.backend.next_id(self.entries)
        entry = Entry(id=new_id, title=title, date=dt, content='', tags=tags, priority=priority)
        self.entries.append(entry)
        self.save()
        self.popup = None
        self._refresh_display()
        # Find and select the new entry
        for i, e in enumerate(self.display_entries):
            if e.id == new_id:
                self.list_idx = i; break
        self._load_editor()

    def _confirm_edit(self):
        e = self._current_entry()
        if e is None: return
        title = self.popup_fields[0].value.strip()
        if not title: return
        date_str = self.popup_fields[1].value.strip()
        dt = parse_date(date_str) or e.date
        priority_str = self.popup_fields[2].value.strip()
        priority = int(priority_str) if priority_str.isdigit() else None
        tags_str = self.popup_fields[3].value.strip()
        tags = [t.strip() for t in tags_str.split(',') if t.strip()]
        e.title = title; e.date = dt; e.priority = priority; e.tags = tags
        self.save(); self.popup = None
        self._refresh_display()

    def _confirm_delete(self):
        e = self.popup_data.get('entry')
        if e is None: return
        self.entries = [x for x in self.entries if x.id != e.id]
        self.save(); self.popup = None
        self._refresh_display()
        if self.display_entries:
            self.list_idx = max(0, min(self.list_idx, len(self.display_entries) - 1))
            self._load_editor()
        else:
            self.editor.load('')

    def _confirm_export_single(self):
        entry = self.popup_data.get('entry')
        if entry is None: return
        path = self.popup_fields[0].value.strip()
        if not path: return
        try:
            os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
            with open(path, 'w', encoding='utf-8') as f:
                f.write(entry.content)
            self.popup = None
            if self.cfg.export_show_confirmation:
                self._show_info(f"Journal content exported to file {path}")
            else:
                self.popup = None
        except Exception as ex:
            self._show_info(f"Export failed: {ex}", 'error')

    def _confirm_export_multi(self):
        path = self.popup_fields[0].value.strip()
        if not path: return
        selected = [e for e in self.entries if e.id in self.multi_selected]
        data = {
            'version': 100,
            'entries': [e.to_transfer_dict() for e in selected]
        }
        try:
            os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
            with open(path, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=2)
            self.popup = None
            self._show_info(f"Journal(s)  exported to file {path}")
        except Exception as ex:
            self._show_info(f"Export failed: {ex}", 'error')

    def _delete_selected(self):
        self.entries = [e for e in self.entries if e.id not in self.multi_selected]
        self.multi_selected.clear()
        self.save(); self._refresh_display()
        if self.display_entries:
            self.list_idx = max(0, min(self.list_idx, len(self.display_entries) - 1))
            self._load_editor()

    def _update_fuzzy(self):
        q = self.fuzzy_query.value
        if q:
            self.fuzzy_results = fuzzy_search(q, self.entries)
        else:
            self.fuzzy_results = []
        self.fuzzy_idx = 0
        self._preview_fuzzy()

    def _preview_fuzzy(self):
        if self.fuzzy_results and 0 <= self.fuzzy_idx < len(self.fuzzy_results):
            target = self.fuzzy_results[self.fuzzy_idx]
            for i, e in enumerate(self.display_entries):
                if e.id == target.id:
                    self.list_idx = i; self._load_editor(); break

    def _cycle_tag_filter(self):
        all_tags = get_all_tags(self.entries)
        if not all_tags: return
        if not self.filter_state.selected_tags:
            self.filter_state.selected_tags = [all_tags[0]]
        else:
            cur = self.filter_state.selected_tags[0] if self.filter_state.selected_tags else None
            idx = all_tags.index(cur) if cur in all_tags else -1
            if idx < len(all_tags) - 1:
                self.filter_state.selected_tags = [all_tags[idx + 1]]
            else:
                self.filter_state.selected_tags = []
        self._refresh_display()

    def _edit_external(self):
        e = self._current_entry()
        if e is None: return
        editor_cmd = (self.cfg.editor_command or
                      os.environ.get('VISUAL') or
                      os.environ.get('EDITOR') or
                      'vi')
        ext = self.cfg.editor_temp_ext
        with tempfile.NamedTemporaryFile(suffix=f'.{ext}', mode='w', delete=False,
                                         encoding='utf-8') as tf:
            tf.write(e.content)
            tmp_path = tf.name
        try:
            subprocess.run([editor_cmd, tmp_path])
            with open(tmp_path, 'r', encoding='utf-8') as f:
                new_content = f.read()
            e.content = new_content
            self.editor.load(new_content)
            if self.cfg.editor_auto_save:
                self.save()
        except Exception:
            pass
        finally:
            try:
                os.unlink(tmp_path)
            except Exception:
                pass


